<!doctype html><html lang="lt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MyGame Admin</title><link rel="stylesheet" href="../assets/admin.css"></head><body>
<aside class="sidebar"><div class="brand">MYGAME <span>ADMIN</span></div><small>VALSTYBĖS</small><div class="country">🇱🇹 <b>Lietuva</b><span>EUR</span></div><nav><?php foreach($admin['sections'] as $key=>$label): ?><a class="<?= $section===$key?'active':'' ?>" href="?section=<?= $key ?>"><?= htmlspecialchars($label) ?></a><?php endforeach; ?></nav><div class="bottom">⚙ Sistemos nustatymai</div></aside>
<main><header><div><small>VALSTYBĖ / LIETUVA</small><h1><?= htmlspecialchars($admin['sections'][$section]) ?></h1></div><div class="admin-badge">ADMINISTRATORIUS</div></header>
<div class="notice"><b>Valstybės ekonomikos valdymas</b><span>Šie parametrai vėliau tiesiogiai veiks žaidėjų įmonių sąnaudas, paklausą ir finansavimą.</span></div>
<section class="content"><div class="section-head"><div><h2><?= htmlspecialchars($admin['sections'][$section]) ?></h2><p>Valdykite šios srities ekonominius parametrus.</p></div><button disabled>Išsaugoti pakeitimus</button></div>
<div class="parameter-list"><?php if(!$parameters): ?><div class="empty">Šio skyriaus parametrus pridėsime kitame etape.</div><?php endif; ?><?php foreach($parameters as $p): ?><div class="parameter"><div><b><?= htmlspecialchars($p->label) ?></b><small><?= htmlspecialchars($p->key) ?></small></div><div class="value"><input type="number" step="0.01" value="<?= htmlspecialchars((string)$p->value) ?>" disabled><span><?= htmlspecialchars($p->unit) ?></span></div></div><?php endforeach; ?></div></section>
</main></body></html>
